59	// ReleasePlan is the deterministic offline release plan.
60	type ReleasePlan struct {
61		App      AppInfo           `json:"app"`
62		Batches  []Batch           `json:"batches"`
63		Excluded []ExcludedCluster `json:"excluded"`
64	}
