66	// ParseReleaseInput reads a release plan document and validates its fields.
67	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
68		dec := json.NewDecoder(bytes.NewReader(data))
69		dec.UseNumber()
70		var doc map[string]any
71		if err := dec.Decode(&doc); err != nil {
72			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
73		}
74		if dec.More() {
75			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
76		}
77	
78		app, err := requiredString(doc, "app")
79		if err != nil {
80			return ReleasePlanInput{}, err
81		}
82		revision, err := requiredString(doc, "revision")
83		if err != nil {
84			return ReleasePlanInput{}, err
85		}
86		image, err := requiredString(doc, "image")
87		if err != nil {
88			return ReleasePlanInput{}, err
89		}
90		batchSize, err := positiveInt(doc, "batchSize")
91		if err != nil {
92			return ReleasePlanInput{}, err
93		}
94		clusters, err := parseClusters(doc["clusters"])
95		if err != nil {
96			return ReleasePlanInput{}, err
97		}
98		include, err := parseConditions(doc["include"], "include")
99		if err != nil {
100			return ReleasePlanInput{}, err
101		}
102		exclude, err := parseConditions(doc["exclude"], "exclude")
103		if err != nil {
104			return ReleasePlanInput{}, err
105		}
106	
107		return ReleasePlanInput{
108			App:       app,
109			Revision:  revision,
110			Image:     image,
111			BatchSize: batchSize,
112			Clusters:  clusters,
113			Include:   include,
114			Exclude:   exclude,
115		}, nil
116	}
117	
118	func requiredString(doc map[string]any, field string) (string, error) {
119		v, ok := doc[field]
120		if !ok {
121			return "", fmt.Errorf("缺少必需字段 %q", field)
122		}
123		s, ok := v.(string)
124		if !ok {
125			return "", fmt.Errorf("字段 %q 必须是字符串", field)
126		}
127		if strings.TrimSpace(s) == "" {
128			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
129		}
130		return s, nil
131	}
132	
133	func positiveInt(doc map[string]any, field string) (int, error) {
134		v, ok := doc[field]
135		if !ok {
136			return 0, fmt.Errorf("缺少必需字段 %q", field)
137		}
138		n, ok := v.(json.Number)
139		if !ok {
140			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
141		}
142		i, err := n.Int64()
143		if err != nil || i <= 0 {
144			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
145		}
146		return int(i), nil
147	}
