149	func parseClusters(v any) ([]Cluster, error) {
150		if v == nil {
151			return nil, errors.New("缺少必需字段 \"clusters\"")
152		}
153		raw, ok := v.([]any)
154		if !ok {
155			return nil, errors.New("字段 \"clusters\" 必须是数组")
156		}
157		clusters := make([]Cluster, 0, len(raw))
158		seen := make(map[string]bool)
159		for i, item := range raw {
160			obj, ok := item.(map[string]any)
161			if !ok {
162				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
163			}
164			id, err := requiredString(obj, "id")
165			if err != nil {
166				return nil, fmt.Errorf("clusters[%d]: %w", i, err)
167			}
168			if seen[id] {
169				return nil, fmt.Errorf("重复的集群标识 %q", id)
170			}
171			seen[id] = true
172	
173			disabled := false
174			if dv, present := obj["disabled"]; present {
175				b, ok := dv.(bool)
176				if !ok {
177					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
178				}
179				disabled = b
180			}
181	
182			tags := map[string]string{}
183			if tv, present := obj["tags"]; present {
184				tm, ok := tv.(map[string]any)
185				if !ok {
186					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
187				}
188				for k, val := range tm {
189					if k == "" {
190						return nil, fmt.Errorf("集群 %q 的标签键不能为空", id)
191					}
192					sv, ok := val.(string)
193					if !ok {
194						return nil, fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k)
195					}
196					tags[k] = sv
197				}
198			}
199	
200			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
201		}
202		return clusters, nil
203	}
204	
205	func parseConditions(v any, field string) ([]LabelCondition, error) {
206		if v == nil {
207			return []LabelCondition{}, nil
208		}
209		raw, ok := v.([]any)
210		if !ok {
211			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
212		}
213		conds := make([]LabelCondition, 0, len(raw))
214		for i, item := range raw {
215			obj, ok := item.(map[string]any)
216			if !ok {
217				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
218			}
219			if len(obj) == 0 {
220				return nil, fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
221			}
222			cond := LabelCondition{}
223			for k, val := range obj {
224				if k == "" {
225					return nil, fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
226				}
227				sv, ok := val.(string)
228				if !ok {
229					return nil, fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k)
230				}
231				cond[k] = sv
232			}
233			conds = append(conds, cond)
234		}
235		return conds, nil
236	}
237	
238	// MakeReleasePlan selects available clusters, orders them by ID, and splits
239	// them into batches. It never mutates the input.
240	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
241		if len(in.Clusters) == 0 {
242			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
243		}
244	
245		selected := []string{}
246		excluded := []ExcludedCluster{}
247		for _, c := range in.Clusters {
248			switch {
249			case c.Disabled:
250				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
251			case matchesAny(c.Tags, in.Exclude):
252				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
253			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
254				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
255			default:
256				selected = append(selected, c.ID)
257			}
258		}
259	
260		sort.Strings(selected)
261		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
262	
263		if len(selected) == 0 {
264			var b strings.Builder
265			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
266			for _, e := range excluded {
267				b.WriteString("\n  ")
268				b.WriteString(e.ID)
269				b.WriteString("：")
270				b.WriteString(e.Reason)
271			}
272			return ReleasePlan{}, errors.New(b.String())
273		}
274	
275		batches := []Batch{}
276		for i := 0; i < len(selected); i += in.BatchSize {
277			end := i + in.BatchSize
278			if end > len(selected) {
279				end = len(selected)
280			}
281			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
282		}
283	
284		return ReleasePlan{
285			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
286			Batches:  batches,
287			Excluded: excluded,
288		}, nil
289	}
290	
291	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
292		for _, cond := range conditions {
293			if matchesAll(tags, cond) {
294				return true
295			}
296		}
297		return false
298	}
299	
300	func matchesAll(tags map[string]string, cond LabelCondition) bool {
301		for k, v := range cond {
302			tv, ok := tags[k]
303			if !ok || tv != v {
304				return false
305			}
306		}
307		return true
308	}
