		"include": [{"env": "dev"}, {"region": "us", "env": "prod"}]
	}`
	p1, err := MakeReleasePlan(parsePlan(t, base))
	if err != nil {
		t.Fatal(err)
	}
	p2, err := MakeReleasePlan(parsePlan(t, shuffled))
	if err != nil {
		t.Fatal(err)
	}
	if len(p1.Batches) != len(p2.Batches) || len(p1.Excluded) != len(p2.Excluded) {
