			tc.mut(&in)
			plan, err := MakeReleasePlan(in)
			if err == nil {
				t.Fatalf("expected error, got plan %+v", plan)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error %q does not mention %s", err.Error(), tc.want)
