	// A valid input with no selectable clusters keeps the existing failure.
	in.Clusters = []Cluster{{ID: "x", Disabled: true}}
	if _, err := MakeReleasePlan(in); err == nil ||
		!strings.Contains(err.Error(), "没有符合规则的可用集群") {
