func TestMake_TagErrorKeyOrderStable(t *testing.T) {
	// The struct path can only observe empty keys; with several empty keys
	// impossible in a map, verify determinism through repeated calls and
	// cover key sorting on the JSON path where distinct invalid keys coexist.
	in := validInput()
	in.Clusters[0].Tags = map[string]string{"": "v", "env": "prod"}
	first, err := MakeReleasePlan(in)
	if err == nil {
		t.Fatal("expected empty-tag-key error")
	}
	for i := 0; i < 10; i++ {
		if _, err := MakeReleasePlan(in); err == nil || err.Error() != firstErrString(err) {
			t.Fatalf("error message varies across calls: %v vs %v", err, first)
		}
	}

	jsonInput := `{
		"app": "app", "revision": "r1", "image": "img", "batchSize": 1,
		"clusters": [{"id": "x", "tags": {"zzz": 1, "aaa": 2}}]
	}`
	_, jerr := ParseReleaseInput([]byte(jsonInput))
	if jerr == nil || !strings.Contains(jerr.Error(), `"aaa"`) {
		t.Fatalf("invalid tag keys must be reported in ascending order, got %v", jerr)
	}
}

func errString(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

func firstErrString(err error) string { return errString(err) }

