func validInput() ReleasePlanInput {
	return ReleasePlanInput{
		App:       "app",
		Revision:  "r1",
		Image:     "img",
		BatchSize: 2,
		Clusters: []Cluster{
			{ID: "c1", Tags: map[string]string{"env": "prod"}},
