	in := ReleasePlanInput{
		App:       " ",
		Revision:  "",
		Image:     "",
		BatchSize: 0,
		Clusters:  []Cluster{{ID: "x"}, {ID: "x"}},
		Include:   []LabelCondition{{}},
		Exclude:   []LabelCondition{{"": "v"}},
